				\begin{document}$${H}_{2}{O}_{2}\, \% =200\times \frac{{I}_{R}/N}{{I}_{D}+{I}_{R}/N}$$\end{document}H2O2%=200×IR/NID+IR/N3\documentclass[12pt]{minimal}
